package demo.sop;

import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class CompilerTest {
    final Compiler compiler=new Compiler();
    static String template(){try{return new String(CompilerTest.class.getResourceAsStream("/template.md").readAllBytes(),StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}}
    @Test void deterministicCompleteTemplate(){var a=compiler.compile(template());assertThat(a.valid()).as(a.issues().toString()).isTrue();assertThat(a).isEqualTo(compiler.compile(template()));assertThat(a.content()).containsOnlyKeys("sop_id","title","owner_team","domain","intent","risk_level","max_autonomy","policy","inputs","rules","actions","boundaries","customer_messages");assertThat((List<?>)a.content().get("rules")).hasSize(2);assertThat(compiler.compile(template().replace("\n","\r\n")).content()).isEqualTo(a.content());}
    @Test void independentFinancialFailures(){String s=template().replace("  max_amount: 200\n","").replace("escalation:\n  - action_id: A1\n    input: refund_amount\n    op: gt\n    amount: 200\n    target_action_id: A2","escalation: []");var r=compiler.compile(s);assertThat(r.content()).isNull();assertThat(r.issues()).extracting(Compiler.Issue::code).contains("REFUND_LIMIT","REFUND_ESCALATION");assertThat(r.issues()).allMatch(i->i.stage().equals("semantic"));}
    @Test void referencesAndTypes(){var r=compiler.compile(template().replace("input: duplicate_confirmed","input: missing").replace("action_ids: [A1]","action_ids: [MISSING]"));assertThat(r.issues()).extracting(Compiler.Issue::code).contains("UNKNOWN_INPUT","UNKNOWN_ACTION");assertThat(compiler.compile(template().replace("value: true","value: 1")).issues()).extracting(Compiler.Issue::code).contains("VALUE_TYPE");assertThat(compiler.compile(template().replace("op: eq","op: gt")).issues()).extracting(Compiler.Issue::code).contains("OPERATOR_TYPE");}
    @Test void rejectsHostileAndAmbiguousYaml(){for(String bad:List.of("title: a\ntitle: b","title: &x Hello\nowner_team: *x","title: !evil hi","title: !!java/object hi","title: .nan","title: [")){var r=compiler.compile(template().replace("title: Refund for Duplicate Charge",bad));assertThat(r.valid()).as(bad).isFalse();assertThat(r.content()).isNull();}assertThat(compiler.compile(template().replace("max_amount: 200","max_amount: .inf")).valid()).isFalse();assertThat(compiler.compile(template().replace("title: Refund for Duplicate Charge","title: "+"[".repeat(21)+"0"+"]".repeat(21))).issues()).extracting(Compiler.Issue::code).contains("YAML_INVALID");}
    @Test void rejectsUnknownFieldsSectionsAndWrongStructures(){for(String s:List.of(template()+"\n## Extra\n- hi",template()+"\n## Actions\n```yaml\n[]\n```",template().replace("owner_team:","unknown:"),template().replace("  type: number","  type: number\n  secret: true"),template().replace("- Fraud is suspected.","prose"),template().replace("max_autonomy: assist","max_autonomy: execute"),template().replace("max_amount: 200","max_amount: '200'"),template().replace("## Actions","# Actions"))){assertThat(compiler.compile(s).valid()).as(s).isFalse();}}
    @Test void semanticUniquenessAndIntent(){assertThat(compiler.compile(template().replace("id: R2","id: R1")).issues()).extracting(Compiler.Issue::code).contains("DUPLICATE_ID");assertThat(compiler.compile(template().replace("intent: refund_duplicate_charge","intent: answer_question")).issues()).extracting(Compiler.Issue::code).contains("REFUND_INTENT");assertThat(compiler.compile(template().replace("    amount: 200","    amount: 201")).issues()).extracting(Compiler.Issue::code).contains("REFUND_ESCALATION");}
    @Test void textIsNeverInterpretedAndIssuesAreSorted(){String html="<script>alert('x')</script>";var r=compiler.compile(template().replace("Refund for Duplicate Charge",html));assertThat(r.valid()).isTrue();assertThat(r.content().get("title")).isEqualTo(html);var invalid=compiler.compile(template().replace("type: number","type: string").replace("domain: Billing","domain: Invalid"));assertThat(invalid.issues()).isSortedAccordingTo(Comparator.comparing(Compiler.Issue::path).thenComparing(Compiler.Issue::code));}
    @Test void byteLimit(){assertThat(compiler.compile("é".repeat(32769)).issues()).extracting(Compiler.Issue::code).contains("SOURCE_TOO_LARGE");}
}
